def prime(self, value, edge=None):
  if type(value) is dict:
    if set(value) == {'path','bytes','sha256'}:
      if edge not in META_EDGES | LEASE_EDGES:
        return
      self.s.body(value)
      if edge not in ('source','canonical','subject') and value['path'] not in self.primed and not _same(value, CATALOGUE_PIN) and not _same(value, self.c['peer_base_catalogue']):
        self.primed.add(value['path'])
        raw = self.s.record(value)
        self.collect(raw, value, review_root=edge in ('different_review','full_proof','different_current_owner_scope_Source_review','different_lease_Source_review','actual_canonical_delta_Source_review','reconciliation_review','tool_review'))
        if edge != 'API':
          self.prime(raw)
      return
    if set(value) == {'canonical','separate_Root_decision','different_review','Root_adoption','original_publication'}:
      self.prime(value['canonical'],'lease_record')
    for key, child in value.items():
      self.prime(child, key)
  elif type(value) is list:
    for child in value:
      self.prime(child, edge)

def input_closure(self, required, roots):
    # Only consumed metadata ABI edges recurse; API descriptive examples/background pins do not.
    edges=('API', 'Root_adoption', 'Root_facts', 'Root_future_path_selection_support', 'actual_Source_packet', 'actual_canonical_delta_Source_review', 'author_packet', 'author_receipt', 'candidate_Root_adoption', 'candidate_author_receipt', 'canonical', 'canonical_delta_Root_adoption', 'content_decision', 'context', 'current_owner_scope', 'current_owner_scope_Root_adoption', 'current_owner_support', 'decision', 'different_current_owner_scope_Source_review', 'different_lease_Source_review', 'different_review', 'execution_witness', 'facts', 'full_proof', 'generation_purpose_support', 'inverse_evidence', 'late_reconciliation', 'lease', 'lease_record', 'new_lease_support', 'original_publication', 'owner_scope', 'peer_packet', 'prewrite_packet', 'producer_purpose', 'producer_purpose_support', 'proposal', 'publication', 'publication_packet', 'receipt', 'reconciliation', 'reconciliation_Root_adoption', 'reconciliation_review', 'request', 'selection', 'separate_Root_decision', 'serialization_witness', 'source', 'stage_return', 'stage_support', 'subject', 'tool_Root_adoption', 'tool_review')
    result={p['path']:copy.deepcopy(p) for p in required};seen=set()
    bypath={r['pin']['path']:r for r in self.b['records']}
    def walk(value, edge=None):
        if type(value)is dict:
            if set(value)=={'path','bytes','sha256'}:
                if edge not in edges and edge not in ('owner_instruction_record','owner_policy_record','current_selection'):return
                result[value['path']]=copy.deepcopy(value)
                if edge in ('source','canonical','subject','Source','owner_instruction_record','owner_policy_record','current_selection') or value['path'] in seen:return
                seen.add(value['path'])
                row=bypath[value['path']];assert row['pin']==value
                decoded=_ow_json(row['body'])
                if edge in ('different_review','full_proof','Root_adoption','current_owner_scope_Root_adoption','different_current_owner_scope_Source_review','different_lease_Source_review','candidate_Root_adoption','actual_canonical_delta_Source_review','canonical_delta_Root_adoption','reconciliation_review','reconciliation_Root_adoption','tool_review','tool_Root_adoption'):
                    for subject in (decoded.get('subjects',[]) if type(decoded)is dict and type(decoded.get('subjects',[]))is list else []):
                        if type(subject)is dict and set(subject)=={'path','bytes','sha256'}and type(subject.get('path'))is str:result[subject['path']]=copy.deepcopy(subject)
                if edge!='API':walk(decoded)
                return
            if set(value)=={'canonical','separate_Root_decision','different_review','Root_adoption','original_publication'}:walk(value['canonical'],'lease_record')
            for key,child in value.items():walk(child,key)
        elif type(value)is list:
            for child in value:walk(child,edge)
    for root in roots:walk(root)
    for name in ('common_catalogue','base_catalogue','role_data','M3_inventory17','historical45','full_historical45'):
        if name in self.b['labels']:result[self.p(name)['path']]=self.p(name)
    return sorted(result.values(),key=lambda p:p['path'])
